/**
 * このファイルは敵として登場するモンスターの強さや、落とすアイテムなどのデータをまとめたファイルです。
 * 
 * モンスターのデータ定義ファイル
 * 
 * 敵キャラクターとして出現するモンスターのステータスやドロップアイテムを定義します。
 * 
 * テンプレート（各項目は省略可能、省略された値は 0 として扱われます）
 *    stats: { hp:    1, atk:   1, def:   1, matk:   1, mdef:   1, spd:   1 },
 *    elements:      { fire: 0, water: 0, grass: 0, ice: 0, thunder: 0, wind: 0, earth: 0, light: 0, dark: 0 },
 *    ailments:      { poison: 0, burn: 0, paralysis: 0, sleep: 0, confusion: 0, curse: 0, blind: 0, silence: 0 },
 */

function createSummonAction(actionName, summonPoolIds, getMonsters) {
  return (attacker, defender, battle) => {
    const MONSTERS = getMonsters();
    const leftDef = MONSTERS.find(m => m.id === summonPoolIds[Math.floor(Math.random() * summonPoolIds.length)]);
    const rightDef = MONSTERS.find(m => m.id === summonPoolIds[Math.floor(Math.random() * summonPoolIds.length)]);
    if (leftDef && rightDef) {
      battle.showActionName(attacker.elementId, actionName, 'text-purple-300', 'border-purple-500/50');
      const createEnemy = (mDef, suffix) => {
        const baseStats = { hp: 0, atk: 0, def: 0, matk: 0, mdef: 0, spd: 0, ...(mDef.stats || {}) };
        return {
          ...mDef,
          stats: {
            ...baseStats,
            attackElements: { fire: 0, water: 0, grass: 0, ice: 0, thunder: 0, wind: 0, earth: 0, light: 0, dark: 0 },
            attackAilments: { poison: 0, burn: 0, paralysis: 0, sleep: 0, confusion: 0, curse: 0, blind: 0, silence: 0 },
            elementResist: { fire: 0, water: 0, grass: 0, ice: 0, thunder: 0, wind: 0, earth: 0, light: 0, dark: 0, ...(mDef.elements || {}) },
            ailmentResist: { poison: 0, burn: 0, paralysis: 0, sleep: 0, confusion: 0, curse: 0, blind: 0, silence: 0, ...(mDef.ailments || {}) }
          },
          uniqueId: `enemy-summon-${Date.now()}-${suffix}`,
          currentHp: baseStats.hp,
          maxHp: baseStats.hp,
          image: `assets/monsters/${mDef.id}.png`,
          atb: 0,
          isDead: false,
          elementId: `enemy-summon-${Date.now()}-${suffix}`
        };
      };
      const attackerIdx = battle.enemies.indexOf(attacker);
      const spaceLeft = 10 - battle.enemies.length;
      const enemiesToAdd = [];
      if (spaceLeft >= 1) enemiesToAdd.push(createEnemy(leftDef, 'L'));
      if (spaceLeft >= 2) enemiesToAdd.push(createEnemy(rightDef, 'R'));

      if (attackerIdx !== -1) {
        if (enemiesToAdd.length === 1) {
          battle.enemies.splice(attackerIdx, 0, enemiesToAdd[0]);
        } else if (enemiesToAdd.length === 2) {
          battle.enemies.splice(attackerIdx, 0, enemiesToAdd[0]);
          battle.enemies.splice(attackerIdx + 2, 0, enemiesToAdd[1]);
        }
      } else {
        battle.enemies.push(...enemiesToAdd);
      }
      attacker.atb = 0;
      battle.elements.enemyArea.innerHTML = '';
      battle.renderEntities();
    }
  };
}

function createAilmentAttack(ailment, chance, actionName, multiplier = 1.2) {
  return (attacker, defender, battle) => {
    const origAilments = attacker.stats.attackAilments;
    attacker.stats.attackAilments = { ...(origAilments || {}), [ailment]: chance };
    battle.executeAttack(attacker, defender, false, { actionName, damageMultiplier: multiplier, isMagic: false, damageType: 'skill' });
    attacker.stats.attackAilments = origAilments;
  };
}

